<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Disable;

use Override;
use Throwable;

use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Disable\ThemeDisableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedDisableAllow
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(private readonly Context $context)
  {
  }
  public function __invoke(ThemeDisableAllowDecision $proposal): ThemeDisableAllowDecision
  {
    $this->logDebug("Check IsAuthenticatedDisableAllow Theme");
    $span = $this->startSpan("Check IsAuthenticatedDisableAllow Theme");
    try {
      $userContext = $this->context->getIdentity();
      if( $proposal->isAllowed()) {
        if( ! !$userContext->anonymous ) {
          $proposal->deny('Disabled if not IsAuthenticatedDisable');
        }      }
      return $proposal;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
